323	static void bicycle_ui_ctl_handle_gnss_sim(map_page_t * page, const char * arg)
324	{
325	    char path[MYVENDOR_BICYCLE_CTL_ARG_MAX];
326	    char toast[80];
327	    const char * p;
328	    const char * rest;
329	    bool reverse = false;
330	    float kph = 0.0f;
331	    float skip_km = 0.0f;
332	    int ret;
333	    char * end = NULL;
334	
335	    if (arg == NULL || arg[0] == '\0' || strcmp(arg, "stop") == 0) {
336	        (void)map_page_gnss_sim(page, NULL, false, 0.0f, 0.0f);
337	        lv_pm_bottom_show("GNSS 模拟已停止", 0);
338	        return;
339	    }
340	
341	    p = arg;
342	    if (strncmp(p, "rev|", 4) == 0) {
343	        reverse = true;
344	        p += 4;
345	    } else if (strncmp(p, "fwd|", 4) == 0) {
346	        p += 4;
347	    }
348	
349	    rest = strchr(p, '|');
350	    if (rest != NULL) {
351	        size_t n = (size_t)(rest - p);
352	
353	        if (n >= sizeof(path)) {
354	            n = sizeof(path) - 1u;
355	        }
356	        memcpy(path, p, n);
357	        path[n] = '\0';
358	        kph = (float)strtod(rest + 1, &end);
359	        if (end == rest + 1) {
360	            kph = 0.0f;
361	        }
362	        if (end != NULL && *end == '|') {
363	            skip_km = (float)strtod(end + 1, NULL);
364	            if (skip_km > 0.0f) {
365	                skip_km = skip_km / 1000.0f;
366	            }
367	        }
368	    } else {
369	        lv_strlcpy(path, p, sizeof(path));
370	    }
371	
372	    if (path[0] == '\0') {
373	        lv_pm_bottom_show("GPX 路径为空", 0);
374	        return;
375	    }
376	
377	    ret = map_page_gnss_sim(page, path, reverse, kph, skip_km);
378	    if (ret != 0) {
379	        snprintf(toast, sizeof(toast), "GPX 打开失败 (%d)", ret);
380	        lv_pm_bottom_show(toast, 0);
381	        return;
382	    }
383	
384	    {
385	        const char * base = strrchr(path, '/');
386	        double at_m = bicycle_gpx_sim_prefix_m();
387	
388	        base = (base != NULL && base[1] != '\0') ? base + 1 : path;
389	        if (at_m >= 50.0) {
390	            snprintf(toast, sizeof(toast), "%s %.36s @%.1fkm",
391	                reverse ? "反向回放" : "顺序回放", base, at_m / 1000.0);
392	        } else {
393	            snprintf(toast, sizeof(toast), "%s %.48s",
394	                reverse ? "反向回放" : "顺序回放", base);
395	        }
396	        lv_pm_bottom_show(toast, 0);
397	    }
398	}
