400	/**
401	 * @brief 自行车 ui ctl parse trip。
402	 */
403	static bool bicycle_ui_ctl_parse_trip(const char * arg,
404	    vmap_route_waypoint_t * out, uint32_t * out_count)
405	{
406	    char buf[MYVENDOR_BICYCLE_CTL_ARG_MAX];
407	    char * save = NULL;
408	    char * seg;
409	    uint32_t n = 0;
410	
411	    if (!arg || !out || !out_count) {
412	        return false;
413	    }
414	
415	    strncpy(buf, arg, sizeof(buf) - 1);
416	    buf[sizeof(buf) - 1] = '\0';
417	
418	    seg = strtok_r(buf, ";", &save);
419	    while (seg != NULL && n < VMAP_ROUTE_TRIP_MAX_WAYPOINTS) {
420	        char * comma = strchr(seg, ',');
421	
422	        if (!comma) {
423	            return false;
424	        }
425	        *comma = '\0';
426	        out[n].lon = atof(seg);
427	        out[n].lat = atof(comma + 1);
428	        n++;
429	        seg = strtok_r(NULL, ";", &save);
430	    }
431	
432	    if (n == 0) {
433	        return false;
434	    }
435	
436	    *out_count = n;
437	    return true;
438	}
