440	static bool bicycle_ui_ctl_trip_from_bridge(vmap_route_waypoint_t * out,
441	    uint32_t * out_count)
442	{
443	    int32_t lat[MYVENDOR_SYS_NAV_MAX_PTS];
444	    int32_t lon[MYVENDOR_SYS_NAV_MAX_PTS];
445	    uint8_t n = 0;
446	    uint8_t i;
447	
448	    if (!out || !out_count) {
449	        return false;
450	    }
451	    if (!myvendor_sys_nav_take(lat, lon, &n) || n == 0) {
452	        return false;
453	    }
454	
455	    for (i = 0; i < n && i < VMAP_ROUTE_TRIP_MAX_WAYPOINTS; i++) {
456	        out[i].lat = (double)lat[i] / 10000000.0;
457	        out[i].lon = (double)lon[i] / 10000000.0;
458	    }
459	    *out_count = i;
460	    return i > 0;
461	}
