559	/**
560	 * @brief 演示模式开关 / 单场景切换 / 循环演示模式（`bicycle_nsh demo` / 菜单）。
561	 * @param arg "on"|"off"|"toggle"（空 = 开）；"run:<场景名>"|"next"|"prev" 单场景；
562	 *            "mode:<模式名>"|"start:<模式名>" 循环演示（random/linear/minghu/full）。
563	 */
564	static void bicycle_ui_ctl_handle_demo(const char * arg)
565	{
566	    char msg[64];
567	    int rc;
568	
569	    /* 循环演示模式：mode:<名>/start:<名>（NSH `demo start|mode|on <name>`）。
570	     * 名字表在 bicycle_demo.h，未知名字提示后直接返回，别落到末尾的通用 toast。 */
571	    if (arg != NULL && (strncmp(arg, "mode:", 5) == 0 ||
572	                        strncmp(arg, "start:", 6) == 0)) {
573	        const char * name = strchr(arg, ':') + 1;
574	        int mode = bicycle_demo_mode_from_name(name);
575	
576	        if (mode < 0) {
577	            lv_pm_bottom_show("Demo: unknown mode", 0);
578	            return;
579	        }
580	
581	        rc = bicycle_demo_start_mode((bicycle_demo_mode_t)mode);
582	        if (rc != BICYCLE_DEMO_OK) {
583	            lv_pm_bottom_show("Demo: mode failed", 0);
584	            return;
585	        }
586	
587	        snprintf(msg, sizeof(msg), "Demo: %s", bicycle_demo_status());
588	        lv_pm_bottom_show(msg, 0);
589	        return;
590	    }
591	
592	    /* 单场景：run:<name> 由 demo 表查找；未知名字要提示，不能静默。 */
593	    if (arg != NULL && strncmp(arg, "run:", 4) == 0) {
594	        if (arg[4] == '\0') {
595	            lv_pm_bottom_show("Demo: unknown scene", 0);
596	            return;
597	        }
598	
599	        rc = bicycle_demo_scene_run(arg + 4);
600	        if (rc == 0) {
